html:
{%- set ctx = get_donation_receipt_context(doc) -%}
<style>
	.np-receipt { font-size: 13px; line-height: 1.5; }
	.np-receipt h2 { font-size: 20px; margin: 0 0 4px; }
	.np-receipt .np-muted { color: #6b7280; }
	.np-receipt table.np-details { width: 100%; margin: 18px 0; border-collapse: collapse; }
	.np-receipt table.np-details td { padding: 6px 0; border-bottom: 1px solid #e5e7eb; vertical-align: top; }
	.np-receipt table.np-details td.np-label { width: 45%; color: #374151; }
	.np-receipt .np-statement { margin-top: 18px; padding: 10px 12px; background: #f3f4f6; border-radius: 4px; }
	.np-receipt .np-total { font-weight: 600; }
</style>

<div class="np-receipt">
	{% if letter_head and not no_letterhead %}
	<div class="letter-head">{{ letter_head }}</div>
	{% endif %}

	<h2>
		{%- if ctx.is_dgr and doc.is_tax_deductible -%}
			{{ _("Tax Deductible Donation Receipt") }}
		{%- else -%}
			{{ _("Donation Receipt") }}
		{%- endif -%}
	</h2>
	<div class="np-muted">{{ _("Receipt No.") }} {{ doc.name }}</div>

	<p style="margin-top: 16px;">
		<b>{{ ctx.organisation }}</b>
		{% if ctx.organisation != ctx.company_name %}<br>{{ _("operated by") }} {{ ctx.company_name }}{% endif %}
		{% if ctx.abn %}<br>{{ _("ABN") }} {{ ctx.abn }}{% endif %}
	</p>

	<table class="np-details">
		<tr>
			<td class="np-label">{{ _("Received from") }}</td>
			<td>{{ doc.donor_name or doc.donor }}</td>
		</tr>
		<tr>
			<td class="np-label">{{ _("Date received") }}</td>
			<td>{{ frappe.utils.format_date(doc.date) }}</td>
		</tr>
		{% if doc.mode_of_payment %}
		<tr>
			<td class="np-label">{{ _("Payment method") }}</td>
			<td>{{ doc.mode_of_payment }}</td>
		</tr>
		{% endif %}
		<tr>
			<td class="np-label">
				{%- if doc.gift_type == "Gift" -%}{{ _("Amount of gift") }}
				{%- else -%}{{ _("Amount of contribution") }}{%- endif -%}
			</td>
			<td>{{ frappe.utils.fmt_money(doc.amount, currency=doc.currency) }}</td>
		</tr>
		{% if doc.gift_type != "Gift" %}
		<tr>
			<td class="np-label">{{ _("GST-inclusive market value of benefit received") }}</td>
			<td>{{ frappe.utils.fmt_money(doc.benefit_value or 0, currency=doc.currency) }}</td>
		</tr>
		{% endif %}
		{% if ctx.is_dgr and doc.is_tax_deductible %}
		<tr class="np-total">
			<td class="np-label">{{ _("Tax deductible amount") }}</td>
			<td>{{ frappe.utils.fmt_money(doc.deductible_amount, currency=doc.currency) }}</td>
		</tr>
		{% endif %}
	</table>

	<div class="np-statement">
		{% if doc.gift_type == "Gift" %}
			{{ _("This receipt is for a gift.") }}
			{% if ctx.is_dgr and doc.is_tax_deductible %}
				{{ _("{0} is endorsed as a deductible gift recipient. No goods or services were provided in return for this gift.").format(ctx.organisation) }}
			{% else %}
				{{ _("This gift is not tax deductible.") }}
			{% endif %}
		{% elif doc.gift_type == "Fundraising Event Contribution" %}
			{{ _("This receipt is for a contribution made for the right to attend or participate in a fundraising event.") }}
			{% if not doc.is_tax_deductible %}{{ _("This contribution is not tax deductible.") }}{% endif %}
		{% elif doc.gift_type == "Auction Contribution" %}
			{{ _("This receipt is for a contribution made for the purchase of goods or services. The contributor was a successful bidder at an auction that was a fundraising event.") }}
			{% if not doc.is_tax_deductible %}{{ _("This contribution is not tax deductible.") }}{% endif %}
		{% endif %}
	</div>

	<p class="np-muted" style="margin-top: 24px;">
		{{ _("Financial year") }} {{ doc.financial_year }} {{ _("(1 July to 30 June)") }}.
		{{ _("Please keep this receipt for your tax records.") }}
	</p>
</div>
